@Dao
interface MindMapDao {
    @Insert
    suspend fun insert(mindMap: MindMapEntity)

    @Query("SELECT * FROM mindmaps WHERE topicId = :topicId")
    suspend fun getByTopicId(topicId: String): MindMapEntity?

    @Insert
    suspend fun insertNode(node: MindMapNode)

    @Query("SELECT * FROM mindmap_nodes WHERE mindMapId = :mindMapId ORDER BY parentId IS NULL DESC, orderIndex ASC")
    suspend fun getNodesByMindMap(mindMapId: String): List<MindMapNode>

    @Update
    suspend fun updateNodeProgress(node: MindMapNode)

    @Query("SELECT * FROM mindmap_nodes WHERE parentId = :parentId ORDER BY orderIndex ASC")
    suspend fun getChildNodes(parentId: String): List<MindMapNode>

    @Query("DELETE FROM mindmap_nodes WHERE mindMapId = :mindMapId")
    suspend fun deleteNodesByMindMap(mindMapId: String)
}

@Database(
    entities = [
        TopicEntity::class,
        MessageEntity::class,
        MindMapEntity::class,
        MindMapNode::class
    ],
    version = 2
)
@TypeConverters(Converters::class)
abstract class AppDatabase : RoomDatabase() {
    abstract fun topicDao(): TopicDao
    abstract fun messageDao(): MessageDao
    abstract fun mindMapDao(): MindMapDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getDatabase(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "teachitback_database"
                ).fallbackToDestructiveMigration().build()
                INSTANCE = instance
                instance
            }
        }
    }
}

data class MindMapItem(
    val mindMap: MindMapEntity,
    val nodes: List<MindMapNode>,
    val isExpanded: Boolean = false
) : RecyclerViewItem {
    override val viewType: Int = R.layout.item_mindmap

    fun getRootNodes(): List<MindMapNode> = nodes.filter { it.parentId == null }

    fun getChildren(parentId: String): List<MindMapNode> = nodes.filter { it.parentId == parentId }

    fun getProgressColor(progress: Int): Int = when {
        progress <= 30 -> Color.RED
        progress <= 70 -> Color.YELLOW
        else -> Color.GREEN
    }

    fun getOverallProgress(): Int {
        return if (nodes.isEmpty()) 0 else nodes.sumOf { it.progress } / nodes.size
    }
}

class MessagesAdapter : ListAdapter<RecyclerViewItem, RecyclerView.ViewHolder>(DIFF_CALLBACK) {

    override fun getItemViewType(position: Int): Int {
        return when (val item = getItem(position)) {
            is TextMessageItem -> R.layout.item_text_message
            is AIResponseItem -> R.layout.item_ai_response
            is MindMapItem -> R.layout.item_mindmap
            else -> throw IllegalArgumentException("Unknown item type")
        }
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        return when (viewType) {
            R.layout.item_mindmap -> MindMapViewHolder(
                LayoutInflater.from(parent.context).inflate(R.layout.item_mindmap, parent, false)
            )
            R.layout.item_text_message -> TextMessageViewHolder(
                LayoutInflater.from(parent.context).inflate(R.layout.item_text_message, parent, false)
            )
            R.layout.item_ai_response -> AIResponseViewHolder(
                LayoutInflater.from(parent.context).inflate(R.layout.item_ai_response, parent, false)
            )
            else -> throw IllegalArgumentException("Unknown view type: $viewType")
        }
    }

    override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
        when (holder) {
            is MindMapViewHolder -> holder.bind(getItem(position) as MindMapItem)
            is TextMessageViewHolder -> holder.bind(getItem(position) as TextMessageItem)
            is AIResponseViewHolder -> holder.bind(getItem(position) as AIResponseItem)
        }
    }
}

class MindMapViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
    private val mindMapContainer: LinearLayout = itemView.findViewById(R.id.mindmap_container)
    private val mindMapTitle: TextView = itemView.findViewById(R.id.mindmap_title)
    private val overallProgress: TextView = itemView.findViewById(R.id.overall_progress)
    private val expandButton: ImageButton = itemView.findViewById(R.id.expand_button)

    fun bind(item: MindMapItem) {
        mindMapTitle.text = item.mindMap.title
        overallProgress.text = "总体进度: ${item.getOverallProgress()}%"

        mindMapContainer.removeAllViews()
        if (item.isExpanded) {
            renderNodes(item.getRootNodes(), item, 0)
            expandButton.setImageResource(R.drawable.ic_collapse)
        } else {
            expandButton.setImageResource(R.drawable.ic_expand)
        }

        expandButton.setOnClickListener {
            // 处理展开/收起逻辑
        }
    }

    private fun renderNodes(nodes: List<MindMapNode>, item: MindMapItem, level: Int) {
        nodes.forEach { node ->
            val nodeView = createNodeView(node, item, level)
            mindMapContainer.addView(nodeView)

            val children = item.getChildren(node.id)
            if (children.isNotEmpty()) {
                renderNodes(children, item, level + 1)
            }
        }
    }

    private fun createNodeView(node: MindMapNode, item: MindMapItem, level: Int): View {
        val inflater = LayoutInflater.from(itemView.context)
        val nodeView = inflater.inflate(R.layout.item_mindmap_node, mindMapContainer, false)

        val nodeTitle: TextView = nodeView.findViewById(R.id.node_title)
        val nodeProgress: TextView = nodeView.findViewById(R.id.node_progress)
        val nodeColor: View = nodeView.findViewById(R.id.node_color)

        nodeTitle.text = node.title
        nodeProgress.text = "${node.progress}%"
        nodeColor.setBackgroundColor(item.getProgressColor(node.progress))

        // 设置缩进
        val params = nodeView.layoutParams as? LinearLayout.LayoutParams
        params?.marginStart = level * 40

        return nodeView
    }
}

class ChatFragment : Fragment() {

    private fun addMindMapToChat(mindMap: MindMapEntity, nodes: List<MindMapNode>) {
        val mindMapItem = MindMapItem(mindMap, nodes)
        val currentList = messagesAdapter.currentList.toMutableList()
        currentList.add(mindMapItem)
        messagesAdapter.submitList(currentList)
        binding.recyclerView.scrollToPosition(currentList.size - 1)
    }

    private suspend fun loadMindMapForTopic(topicId: String) {
        val mindMap = database.mindMapDao().getByTopicId(topicId)
        mindMap?.let { map ->
            val nodes = database.mindMapDao().getNodesByMindMap(map.id)
            addMindMapToChat(map, nodes)
        }
    }

    private fun handleAIResponseWithProgress(response: AIResponse) {
        response.progressUpdates?.forEach { (nodeId, progress) ->
            viewModelScope.launch {
                val node = database.mindMapDao().getNodeById(nodeId)
                node?.let {
                    val updatedNode = it.copy(progress = progress)
                    database.mindMapDao().updateNodeProgress(updatedNode)
                }
            }
        }
    }
}

class WhyFragment : Fragment() {

    private val presetTopics = listOf(
        TopicEntity(
            id = "preset_biology",
            title = "高中三年级生物",
            description = "标准高中生物课程",
            isPreset = true
        ),
        TopicEntity(
            id = "preset_physics",
            title = "高中物理",
            description = "基础物理知识",
            isPreset = true
        )
    )

    private fun setupPresetTopics() {
        val adapter = PresetTopicsAdapter(presetTopics) { topic ->
            copyPresetTopic(topic)
        }
        binding.presetTopicsRecyclerView.adapter = adapter
    }

    private fun copyPresetTopic(presetTopic: TopicEntity) {
        val personalTopic = presetTopic.copy(
            id = UUID.randomUUID().toString(),
            isPreset = false
        )
        viewModelScope.launch {
            database.topicDao().insert(personalTopic)
            findNavController().navigate(R.id.action_whyFragment_to_chatFragment)
        }
    }
}

class PresetTopicsAdapter(
    private val topics: List<TopicEntity>,
    private val onTopicSelected: (TopicEntity) -> Unit
) : RecyclerView.Adapter<PresetTopicsAdapter.ViewHolder>() {

    class ViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val title: TextView = itemView.findViewById(R.id.topic_title)
        val description: TextView = itemView.findViewById(R.id.topic_description)
        val presetBadge: TextView = itemView.findViewById(R.id.preset_badge)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_preset_topic, parent, false)
        return ViewHolder(view)
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        val topic = topics[position]
        holder.title.text = topic.title
        holder.description.text = topic.description
        holder.presetBadge.visibility = if (topic.isPreset) View.VISIBLE else View.GONE

        holder.itemView.setOnClickListener {
            onTopicSelected(topic)
        }
    }

    override fun getItemCount() = topics.size
}

@RunWith(AndroidJUnit4::class)
class MindMapDaoTest {

    private lateinit var database: AppDatabase
    private lateinit var mindMapDao: MindMapDao

    @Before
    fun createDb() {
        val context = ApplicationProvider.getApplicationContext<Context>()
        database = Room.inMemoryDatabaseBuilder(context, AppDatabase::class.java).build()
        mindMapDao = database.mindMapDao()
    }

    @After
    fun closeDb() {
        database.close()
    }

    @Test
    fun testInsertAndRetrieveMindMap() = runTest {
        val mindMap = MindMapEntity(topicId = "test_topic", title = "Test MindMap")
        mindMapDao.insert(mindMap)

        val retrieved = mindMapDao.getByTopicId("test_topic")
        assertThat(retrieved).isNotNull()
        assertThat(retrieved?.title).isEqualTo("Test MindMap")
    }
}

fun initializeMindMapDemoData() {
    CoroutineScope(Dispatchers.IO).launch {
        val database = AppDatabase.getDatabase(context)

        // 清除现有MindMap数据
        database.mindMapDao().deleteAllMindMaps()

        // 创建预置课程MindMap
        val presetTopics = listOf(
            "高中三年级生物",
            "高中物理",
            "高中化学",
            "微积分基础",
            "编程入门"
        )

        presetTopics.forEach { title ->
            val topic = TopicEntity(
                title = title,
                description = "标准${title}课程",
                isPreset = true
            )
            database.topicDao().insert(topic)

            // 创建对应的MindMap
            val mindMap = MindMapEntity(
                topicId = topic.id,
                title = "${title}学习路径"
            )
            database.mindMapDao().insert(mindMap)

            // 为每个预置课程创建标准MindMap结构
            when (title) {
                "高中三年级生物" -> createBiologyMindMap(mindMap.id, database)
                "高中物理" -> createPhysicsMindMap(mindMap.id, database)
                "高中化学" -> createChemistryMindMap(mindMap.id, database)
                "微积分基础" -> createCalculusMindMap(mindMap.id, database)
                "编程入门" -> createProgrammingMindMap(mindMap.id, database)
            }
        }
    }
}

private suspend fun createBiologyMindMap(mindMapId: String, database: AppDatabase) {
    val nodes = listOf(
        MindMapNode(mindMapId = mindMapId, title = "细胞生物学", progress = 0),
        MindMapNode(mindMapId = mindMapId, title = "遗传学", progress = 0),
        MindMapNode(mindMapId = mindMapId, title = "生态学", progress = 0),
        MindMapNode(mindMapId = mindMapId, title = "生物进化", progress = 0),
        MindMapNode(mindMapId = mindMapId, title = "人体生理", progress = 0)
    )
    nodes.forEach { database.mindMapDao().insertNode(it) }
}

class PresetMindMapCreator(private val database: AppDatabase) {

    suspend fun createDetailedMindMapStructure(mindMapId: String, subject: String) {
        when (subject) {
            "高中三年级生物" -> createDetailedBiologyStructure(mindMapId)
            "高中物理" -> createDetailedPhysicsStructure(mindMapId)
            // ... 其他科目
        }
    }

    private suspend fun createDetailedBiologyStructure(mindMapId: String) {
        // 创建根节点
        val cellBiology = MindMapNode(mindMapId = mindMapId, title = "细胞生物学")
        database.mindMapDao().insertNode(cellBiology)

        // 创建子节点
        val cellStructure = MindMapNode(mindMapId = mindMapId, parentId = cellBiology.id, title = "细胞结构", progress = 0)
        val cellFunction = MindMapNode(mindMapId = mindMapId, parentId = cellBiology.id, title = "细胞功能", progress = 0)
        val cellDivision = MindMapNode(mindMapId = mindMapId, parentId = cellBiology.id, title = "细胞分裂", progress = 0)

        listOf(cellStructure, cellFunction, cellDivision).forEach { database.mindMapDao().insertNode(it) }

        // 创建孙子节点
        val dnaStructure = MindMapNode(mindMapId = mindMapId, parentId = cellStructure.id, title = "DNA结构", progress = 0)
        val rnaFunction = MindMapNode(mindMapId = mindMapId, parentId = cellFunction.id, title = "RNA功能", progress = 0)
        val mitosis = MindMapNode(mindMapId = mindMapId, parentId = cellDivision.id, title = "有丝分裂", progress = 0)
        val meiosis = MindMapNode(mindMapId = mindMapId, parentId = cellDivision.id, title = "减数分裂", progress = 0)

        listOf(dnaStructure, rnaFunction, mitosis, meiosis).forEach { database.mindMapDao().insertNode(it) }
    }
}

class MindMapDemoValidator(private val database: AppDatabase) {

    suspend fun validateDemoData(): ValidationResult {
        val presetTopics = database.topicDao().getPresetTopics()
        val errors = mutableListOf<String>()

        // 验证预置课程数量
        if (presetTopics.isEmpty()) {
            errors.add("未找到预置课程")
        }

        // 验证每个预置课程都有对应的MindMap
        presetTopics.forEach { topic ->
            val mindMap = database.mindMapDao().getByTopicId(topic.id)
            if (mindMap == null) {
                errors.add("${topic.title} 没有对应的MindMap")
            } else {
                val nodes = database.mindMapDao().getNodesByMindMap(mindMap.id)
                if (nodes.isEmpty()) {
                    errors.add("${topic.title} 的MindMap为空")
                }
            }
        }

        return ValidationResult(
            isValid = errors.isEmpty(),
            errors = errors,
            totalTopics = presetTopics.size
        )
    }

    data class ValidationResult(
        val isValid: Boolean,
        val errors: List<String>,
        val totalTopics: Int
    )
}
